/** 한 문제의 영역 PNG URL — 없으면 undefined (정답 결측 또는 미업로드). */
export function getSuneungQuestionImage(
  subject: Subject,
  variant: ExamVariant,
  year: number,
  number: number,
): string | undefined {
  const e = SUNEUNG_QUESTIONS_RAW.find(
    (x) =>
      x.subject === subject &&
      x.variant === variant &&
      x.year === year &&
      x.number === number,
  );
  return e?.url;
}
